  /* الشريط المتري: صفره على سطح وسادة الاستقبال */
  const tx0=X0+648*k,tx1=X0+698*k,tTop=Y0+205*k;
  g+=`<rect x="${F(tx0)}" y="${F(tTop)}" width="${F(tx1-tx0)}" height="${F(pad-tTop)}" fill="#FACC15" stroke="#A16207" stroke-width=".8"/>`;
  for(let i=0;i<=Math.floor((pad-tTop)/K*20+1e-9);i++){const y=pad-i*K/20,big=i%2===0;g+=`<line x1="${F(tx1)}" y1="${F(y)}" x2="${F(tx1-(big?7:4))}" y2="${F(y)}" stroke="#1F2937" stroke-width="${big?1.1:.6}"/>`+(big?`<text x="${F(tx0+2)}" y="${F(y+3)}" font-size="7" font-weight="800" fill="#1F2937">${i*5}</text>`:'')}
  /* ماسك الشريط: يربط أعلى الشريط بأسفل جهاز الإفلات */
  {const cx0=tx0-5,cw=tx1-tx0+10,cy=tTop-7;g+=`<rect x="${F(cx0)}" y="${F(cy)}" width="${F(cw)}" height="15" rx="2.5" fill="#64748B" stroke="#1E293B" stroke-width="1"/><rect x="${F(cx0+1.5)}" y="${F(cy+1.5)}" width="${F(cw-3)}" height="4" rx="1.5" fill="#CBD5E1" opacity=".55"/>`+[cx0+4.5,cx0+cw-4.5].map(x=>`<circle cx="${F(x)}" cy="${F(cy+8.5)}" r="2.3" fill="#E2E8F0" stroke="#334155" stroke-width=".8"/><line x1="${F(x-1.5)}" y1="${F(cy+8.5)}" x2="${F(x+1.5)}" y2="${F(cy+8.5)}" stroke="#334155" stroke-width=".7"/>`).join('')}
  g+=`<rect x="${F(tx0-1)}" y="${F(pad-2)}" width="${F(tx1-tx0+2)}" height="3.5" fill="#F7931E" stroke="#9A3412" stroke-width=".6"/>`;
