  const SB=(x0,x1,y,d,t)=>`<path d="M${F(x0+d)},${F(y-d*.7)} L${F(x1+d)},${F(y-d*.7)} L${F(x1)},${F(y)} L${F(x0)},${F(y)}Z" fill="#64748B" stroke="#1F2937" stroke-width=".8"/><rect x="${F(x0)}" y="${F(y)}" width="${F(x1-x0)}" height="${t}" fill="#334155" stroke="#1F2937" stroke-width=".8"/><path d="M${F(x1)},${F(y)} L${F(x1+d)},${F(y-d*.7)} L${F(x1+d)},${F(y-d*.7+t)} L${F(x1)},${F(y+t)}Z" fill="#1E293B" stroke="#1F2937" stroke-width=".8"/>`;
