   g+=`<line x1="${l1}" y1="${py}" x2="${l1}" y2="${yl}" stroke="#7C2D12" stroke-width="2.4"/><line x1="${r1}" y1="${py}" x2="${r1}" y2="${yr}" stroke="#7C2D12" stroke-width="2.4"/>`;
