  g+=`<polygon points="8,${TY} ${W-20},${TY} ${W-6},${TY-26} 26,${TY-26}" fill="url(#pbWd)" stroke="#9A6A3A"/><rect x="8" y="${TY}" width="${W-28}" height="14" fill="#B07A44" stroke="#7C4A1F"/><polygon points="${W-20},${TY} ${W-6},${TY-26} ${W-6},${TY-12} ${W-20},${TY+14}" fill="#8E5A2C" stroke="#7C4A1F" stroke-linejoin="round"/>`;
