   for(let i=0;i<=10;i++){const c=S(sx0+12+i*(sx1-sx0-20)/10,30,35);g+=`<line x1="${c[0]}" y1="${c[1]}" x2="${c[0]}" y2="${c[1]-(i%5?3:6)}" stroke="#1F2937" stroke-width="0.8"/>`}
