  g+=`<text x="${F(pp[0])}" y="${F(pp[1]-9)}" font-size="12" font-weight="700" text-anchor="middle" fill="#fff">+</text><text x="${F(pn[0])}" y="${F(pn[1]-9)}" font-size="12" font-weight="700" text-anchor="middle" fill="#fff">−</text>`;
