  const hole=(x,d)=>{const p=S(x,d,ZT+.1);return `<rect x="${F(p[0]-2.4)}" y="${F(p[1]-1.7)}" width="4.8" height="3.4" fill="#0F172A" rx=".6"/>`},hp=(x,d)=>S(x,d,ZT+.2);
