    const dx=b[0]-a[0],dy=b[1]-a[1],L=Math.hypot(dx,dy),ang=Math.atan2(dy,dx)*180/Math.PI,cx=(a[0]+b[0])/2,cy=(a[1]+b[1])/2,hh=8.5;
    g+=`<g transform="translate(${F(cx)} ${F(cy)}) rotate(${F(ang)})"><rect x="${F(-L/2)}" y="${-hh}" width="${F(L)}" height="${2*hh}" rx="${hh}" fill="url(#srR)" stroke="#1E3A8A"/>`+[0.16,0.3,0.44,0.8].map((t,i)=>`<rect x="${F(-L/2+L*t)}" y="${-hh}" width="4.5" height="${2*hh}" fill="${bc[i]}" stroke="#0F172A" stroke-width=".4"/>`).join('')+`</g>`;
    const p1=S(xa,DP,zb),p2=S(xb,DP,zb);g+=`<text x="${F(p1[0]-4)}" y="${F(p1[1]-8)}" font-size="12" font-weight="900" fill="#DC2626" text-anchor="middle">+</text><text x="${F(p2[0]+4)}" y="${F(p2[1]-8)}" font-size="13" font-weight="900" fill="#2563EB" text-anchor="middle">−</text>`;
