  const jump=([p,q],f)=>{const lz=ZT+.6+f*55,dx=-f*30,h=lz+12,a0=S(p[0]+dx,p[1],lz),a1=S(p[0]+dx,p[1],h),b1=S(q[0]+dx,q[1],h),b0=S(q[0]+dx,q[1],lz);return wire([a0,a1,b1,b0],'#7C2D12',6.5)+wire([a0,a1,b1,b0],'#F7931E',4)};
